export function getAllAvailableTools() {
  return toolMeta
}

export function getToolCategories() {
  const seen = new Set<string>()
  return toolMeta
    .filter(t => {
      if (seen.has(t.category)) return false
      seen.add(t.category)
      return true
    })
    .map(t => ({ category: t.category }))
}
